def is_golomb(marks):
    n = len(marks)
    diffs = set()
    for i in range(n):
        for j in range(i+1, n):
            d = marks[j] - marks[i]
            if d in diffs:
                return False
            diffs.add(d)
    return True

# Test known optimal Golomb ruler of order 5
marks = [0,1,4,9,11]
print("Marks:", marks)
print("Valid Golomb ruler:", is_golomb(marks))
diffs = []
for i in range(len(marks)):
    for j in range(i+1, len(marks)):
        diffs.append(marks[j]-marks[i])
print("Differences:", sorted(diffs))
print("All unique:", len(diffs) == len(set(diffs)))
